function verifyJWT(auth){
  const crypto = require('crypto');
  const SECRET = 'yavibot-dev-secret-change-me';
  if(!auth || !auth.startsWith('Bearer ')) return null;
  const parts = auth.slice(7).split('.');
  if(parts.length !== 3) return null;
  const [h,p,s] = parts;
  const b64 = b => Buffer.from(b).toString('base64').replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_');
  if(b64(crypto.createHmac('sha256', SECRET).update(h+'.'+p).digest()) !== s) return null;
  let c; try { c = JSON.parse(Buffer.from(p.replace(/-/g,'+').replace(/_/g,'/'),'base64').toString()); } catch(e){ return null; }
  if(c.exp && c.exp < Math.floor(Date.now()/1000)) return null;
  return c;
}
function unauth(){ return [{ json: { _status:401, _body:{ ok:false, error:{ code:'NO_AUTENTICADO', message:'Sesión no válida' } } } }]; }
function forbidden(){ return [{ json: { _status:403, _body:{ ok:false, error:{ code:'SIN_PERMISO', message:'No autorizado' } } } }]; }

const { Client } = require('pg');
const crypto = require('crypto');
const nodemailer = require('nodemailer');
const fs = require('fs');
const claims = verifyJWT($json.headers.authorization || $json.headers.Authorization);
if(!claims) return unauth();
// Reportar una incidencia esta abierto a todo el personal del panel:
// docentes, coordinacion, vinculacion y secretaria. Quien la GESTIONA
// (cambia el estado) sigue siendo solo el rol con ALERTA_LAB asignada.
const body = $json.body || {};
const laboratorio_id = Number(body.laboratorio_id || 0);
const descripcion = String(body.descripcion || '').trim();
const foto = String(body.foto || '');
if(!laboratorio_id || !descripcion)
  return [{ json: { _status:400, _body:{ ok:false, error:{ code:'VALIDACION', message:'Complete el laboratorio y la descripción de la incidencia' } } } }];

// Validar imagen (data URL)
const m = foto.match(/^data:(image\/(png|jpeg));base64,(.+)$/);
if(!m) return [{ json: { _status:400, _body:{ ok:false, error:{ code:'ARCHIVO_INVALIDO', message:'La foto debe ser JPG o PNG' } } } }];
const mime = m[1];
const buf = Buffer.from(m[3], 'base64');
if(buf.length > 5*1024*1024) return [{ json: { _status:400, _body:{ ok:false, error:{ code:'ARCHIVO_INVALIDO', message:'La foto supera 5 MB' } } } }];

const client = new Client({host:'postgres',port:5432,user:'yavibot',password:'yavibot_dev_2026',database:'yavibot'});
await client.connect();
try {
  const ext = mime === 'image/png' ? 'png' : 'jpg';
  const name = crypto.randomUUID() + '.' + ext;
  const hash = crypto.createHash('sha256').update(buf).digest('hex');
  fs.writeFileSync('/data/storage/uploads/' + name, buf);
  const adj = (await client.query(
    `INSERT INTO adjuntos (tipo, ruta, mime, tamano_bytes, hash) VALUES ('foto_alerta',$1,$2,$3,$4) RETURNING id`,
    ['storage/uploads/' + name, mime, buf.length, hash])).rows[0];

  const ins = (await client.query(
    `INSERT INTO alertas (codigo, laboratorio_id, descripcion, adjunto_id, profesor_id, estado)
     VALUES ('TMP',$1,$2,$3,$4,'Pendiente') RETURNING id`,
    [laboratorio_id, descripcion, adj.id, Number(claims.sub)])).rows[0];
  const codigo = 'AL-' + String(ins.id).padStart(6, '0');
  await client.query('UPDATE alertas SET codigo=$1 WHERE id=$2', [codigo, ins.id]);

  // Responsables = usuarios activos cuyo ROL audita las alertas de laboratorio
  const resps = (await client.query(
    `SELECT u.id, u.nombres, u.correo FROM usuarios_panel u
       JOIN rol_tipos_solicitud rt ON rt.rol_id = u.rol_id
       JOIN tipos_solicitud t ON t.id = rt.tipo_solicitud_id
     WHERE t.codigo = 'ALERTA_LAB' AND u.activo = true ORDER BY u.id`)).rows;
  const resp = resps[0] || null;
  if(resp) await client.query('UPDATE alertas SET responsable_id=$1 WHERE id=$2', [resp.id, ins.id]);
  await client.query('INSERT INTO alerta_historial (alerta_id, estado_nuevo, usuario_id) VALUES ($1,$2,$3)',
    [ins.id, 'Pendiente', Number(claims.sub)]);
  await client.query("INSERT INTO eventos (tipo, payload, origen) VALUES ('AlertaCreada',$1,'panel')",
    [JSON.stringify({ alerta_id: ins.id, codigo })]);

  // Notificación informativa: qué pasó, cuándo y quién lo reportó
  if(resps.length) {
    const _rawtx = nodemailer.createTransport({ host: $env.SMTP_HOST, port: Number($env.SMTP_PORT||465), secure: String($env.SMTP_SECURE||'true')!=='false', auth: $env.SMTP_USER ? { user: $env.SMTP_USER, pass: $env.SMTP_PASS } : undefined, tls: { rejectUnauthorized: false } }); const tx = { sendMail: async (m) => { try { return await _rawtx.sendMail(m); } catch(e) { console.log('YaviBot: correo no enviado -', e.message); } } };
    const d = (await client.query(
      `SELECT l.nombre AS laboratorio, p.nombres AS reporta, p.correo AS reporta_correo,
              to_char(a.creado_en AT TIME ZONE 'America/Guayaquil','DD/MM/YYYY') AS fecha,
              to_char(a.creado_en AT TIME ZONE 'America/Guayaquil','HH24:MI')    AS hora
         FROM alertas a JOIN laboratorios l ON l.id = a.laboratorio_id
         JOIN usuarios_panel p ON p.id = a.profesor_id
        WHERE a.id = $1`, [ins.id])).rows[0];
    for(const r of resps) {
      await tx.sendMail({ from: ($env.SMTP_FROM || $env.SMTP_USER || 'no-reply@yavibot.local'), to: r.correo,
        subject:`Nueva incidencia de laboratorio ${codigo} — ${d.laboratorio}`,
        text:`Hola ${r.nombres},\n\nNotificación informativa: se ha reportado una nueva incidencia de laboratorio.\n\n`+
             `Código:       ${codigo}\nLaboratorio:  ${d.laboratorio}\n`+
             `Reportado por: ${d.reporta} (${d.reporta_correo})\n`+
             `Fecha:        ${d.fecha}\nHora:         ${d.hora}\n`+
             `Descripción:  ${descripcion}\n`+
             `\nIngrese al panel para gestionarla.\n\nInstituto Superior Tecnológico Yavirac` });
    }
  }
  return [{ json: { _status:200, _body:{ ok:true, data:{ codigo, estado:'Pendiente' } } } }];
} finally { await client.end(); }
